    def __init__(self):
        super().__init__(convert_charrefs=True); self.stack=[]; self.errs=[]
    def handle_starttag(self,tag,attrs):
        if tag not in ('meta','link','img','br','hr','input','source','path','circle','rect','text','use'):
            self.stack.append(tag)
    def handle_endtag(self,tag):
        if not self.stack: self.errs.append('extra close '+tag); return
        if self.stack[-1]==tag: self.stack.pop()
        else:
            self.errs.append(f'mismatch: expected {self.stack[-1]} got {tag} at {self.getpos()}')
